nslation": "სამუშაოს შემდეგ ხშირად სასეირნოდ მივდივართ.", "highlight": "Feierabend", "phoneticKa": "ნახ ფაირაბენდ გეენ ვირ ოფტ შპაციერენ."}], "grammarTip": "მამრობითი სქესის არსებითი სახელია: der Feierabend.", "commonMistakes": [{"wrong": "Ich habe die Feierabend.", "correct": "Ich habe Feierabend.", "reason": "ამ გამოთქმაში არტიკლი არ გამოიყენება: Feierabend haben."}]}, "lexicalRelations": {"synonyms": [{"term": "Arbeitsende", "nuance": "უფრო ოფიციალური"}, {"term": "Dienstschluss", "nuance": "სამსახურებრივი, ოფიციალური"}], "antonyms": [{"term": "Arbeitsbeginn", "translation": "სამუშაოს დაწყება"}], "confusables": [{"term": "Feiertag", "difference": "Feiertag არის დასვენების დღე (დღესასწაული), Feierabend კი სამუშაო დღის დასასრული."}]}, "exercises": {"quizDistractors": ["სადილის დრო", "დღესასწაულის დღე", "სამუშაოს დაწყება"], "fillInTheBlank": {"prompt": "Um sechs Uhr habe ich endlich _______.", "answer": "Feierabend", "hint": "იწყება “Feier...”-ით"}}, "mediaAndSystem": {"audio": {"ttsEngine": "WebSpeechAPI", "speechRate": 0.9, "customAudioUrl": null}, "srsMetadata": {"xpValue": 20, "initialIntervalDays": 1, "easeFactor": 2.5}, "createdAt": "2026-11-26T09:00:00Z", "author": "Peera.My demo"}}$json$::jsonb)
